44	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
45	                members.add(existing);
46	            }
47	        }
48	        if (members.isEmpty()) {
49	            return; // no existing household — a plain unique owner, no householdId
50	        }
51	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
52	            throw new DuplicateOwnerHouseholdException(request.getLastName(), request.getAddress());
53	        }
54	        // Opted in to share the household: assign the same stable id to every member.
55	        String id = deriveHouseholdId(lastName, address);
56	        for (Owner member : members) {
57	            member.setHouseholdId(id);
58	            ownerRepository.save(member);
59	        }
60	        householdId.set(new HouseholdId(id));
61	    }
62	
63	    /**
64	     * A stable household identifier derived from the canonical last name and address, so that
65	     * every owner joining the same household independently derives an identical value.
66	     */
