69	        try {
70	            byte[] digest = MessageDigest.getInstance("SHA-256")
71	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
72	            StringBuilder hex = new StringBuilder();
73	            for (int i = 0; i < 6; i++) {
